bodies.metal:
float2 displacement=float2(0,0);
if (ripple > 0.5) {
    float2 delta=uv-float2(0.5,0.5);
    float distance=length(delta);
    displacement=delta/max(distance,0.00001)*sin(distance*frequency-time)*strength;
} else {
    displacement=float2(sin(uv.y*frequency+time)*strength,sin(uv.x*frequency*0.7-time)*strength*0.3);
}
return uv+displacement;

